impl From<PwrightKeyboardErrorDetails> for PublicKeyboardErrorDetails {
    fn from(value: PwrightKeyboardErrorDetails) -> Self {
        match value {
            PwrightKeyboardErrorDetails::InvalidKey { message } => Self::InvalidKey(message),
            PwrightKeyboardErrorDetails::Resource { message } => Self::Resource(message),
            PwrightKeyboardErrorDetails::Backend { message } => Self::Backend(message),
        }
    }
}

impl From<PublicKeyboardErrorDetails> for PwrightKeyboardErrorDetails {
    fn from(value: PublicKeyboardErrorDetails) -> Self {
        match value {
            PublicKeyboardErrorDetails::InvalidKey(message) => Self::InvalidKey { message },
            PublicKeyboardErrorDetails::Resource(message) => Self::Resource { message },
            PublicKeyboardErrorDetails::Backend(message) => Self::Backend { message },
        }
    }
}

